mapper.select:
select

from sys_tag t
left join sys_tag_sequence ts on (ts.tag_id = t.id

    and ts.biz_id in

        #{bizId}


)
where t.active = 1
and t.biz_type = #{request.bizType}

    and t.tenant_id in (0, #{request.tenantId})


    and t.biz_id in

        #{bizId}



    and (t.title like concat('%', #{request.q}, '%') or t.description like concat('%', #{request.q}, '%'))

order by coalesce(ts.idx, 0), t.idx, t.updated_at desc
